38	\centering
39	\includegraphics[width=0.95\textwidth]{slides-images/slide-47.jpg}
40	\caption{训练 RL 在真实世界中应用的难点：运行策略（步骤2）可能导致危险\protect\footnotemark}
41	\end{figure}
42	\footnotetext{Slides 第47页。}
